from datetime import datetime, timezone
from typing import Literal, Optional
from pydantic import BaseModel, Field


class SubQuestion(BaseModel):
    """A granular, well-scoped sub-question generated by the Planner."""
    id: str = Field(description="Unique identifier, e.g. 'sq_1'")
    question: str = Field(description="Specific research sub-question")
    rationale: str = Field(description="Why this sub-question is critical to resolving the main topic")
    expected_evidence: str = Field(description="The concrete evidence or metrics needed to answer this")
    status: Literal["pending", "in_progress", "completed", "failed"] = Field(
        default="pending", description="Current execution status of the sub-question"
    )
    attempts: int = Field(default=0, description="Number of researcher attempts executed for this question")


class ResearchPlan(BaseModel):
    """Structured research plan produced by the Planner specialist."""
    research_topic: str = Field(description="The primary user research topic or query")
    sub_questions: list[SubQuestion] = Field(
        description="Structured sub-questions, capped to budget constraints"
    )
    strategy_overview: str = Field(
        default="", description="High-level synthesis strategy and research scope"
    )


class EvidenceRecord(BaseModel):
    """A verified unit of evidence gathered by the Researcher with source provenance."""
    claim: str = Field(description="The factual claim or insight discovered")
    source_url: str = Field(description="Source URL where this finding originated")
    domain: str = Field(description="Normalized domain name of the source (e.g. 'arxiv.org')")
    snippet: str = Field(description="Key snippet quotation supporting the claim")
    extracted_text: Optional[str] = Field(
        default=None, description="Clean full text extracted from the webpage if available"
    )
    retrieval_timestamp: str = Field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat(),
        description="ISO 8601 UTC timestamp of retrieval"
    )
    confidence: float = Field(
        default=1.0, ge=0.0, le=1.0, description="Heuristic or LLM confidence score for this finding"
    )


class SearchStatus(BaseModel):
    """Structured status returned by live search tools, replacing unhandled exceptions."""
    status: Literal["success", "no_results", "rate_limited", "paywalled", "timeout", "error"]
    error_message: Optional[str] = None
    query: str = ""
    result_count: int = 0


class ResearcherOutput(BaseModel):
    """Structured output returned by the Researcher specialist for one sub-question."""
    sub_question_id: str
    findings: list[EvidenceRecord] = Field(default_factory=list)
    search_status: SearchStatus
    searches_executed: int = Field(default=1, ge=0)
    summary: str = Field(default="", description="Researcher's concise synthesis of the findings")


class SupervisorReview(BaseModel):
    """Supervisor critique and routing decision on a researcher pass."""
    is_sufficient: bool = Field(
        description="True if findings adequately answer the sub-question with credible sources"
    )
    feedback: str = Field(description="Specific feedback or missing aspects if insufficient")
    allow_retry: bool = Field(
        description="Whether a retry pass is permitted under the 1-revision budget cap"
    )
    next_action: Literal[
        "continue_research", "retry_subquestion", "synthesize_report", "abort_budget_exceeded"
    ]


class Citation(BaseModel):
    """Individual citation record linking report statements to retrieved evidence."""
    citation_id: str = Field(description="Numeric or alphanumeric tag, e.g. '[1]'")
    source_url: str = Field(description="Original URL citation points to")
    domain: str = Field(description="Domain name for attribution")
    claim_supported: str = Field(description="The claim directly supported by this citation")
    snippet_reference: str = Field(description="Referenced snippet evidence")
    is_verified: bool = Field(
        default=False, description="Set to True by citation validator if matched to an EvidenceRecord"
    )


class ReportSection(BaseModel):
    """Section of the final research report."""
    heading: str
    content: str
    citation_ids: list[str] = Field(
        default_factory=list, description="IDs of citations referenced in this section"
    )


class ResearchReport(BaseModel):
    """Final comprehensive research report generated by the Writer specialist."""
    topic: str
    executive_summary: str
    sections: list[ReportSection] = Field(default_factory=list)
    citations: list[Citation] = Field(default_factory=list)
    unresolved_questions: list[str] = Field(
        default_factory=list, description="Sub-questions that could not be fully answered"
    )
    completion_status: Literal["complete", "partial_budget_exhausted", "failed"] = "complete"


class StepTrace(BaseModel):
    """Audit log entry representing a single step execution in the graph."""
    step_id: str
    node_name: str
    timestamp: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    latency_ms: float = 0.0
    tokens_used: int = 0
    input_summary: str = ""
    output_summary: str = ""
    tool_calls: list[dict] = Field(default_factory=list)


class RunStatus(BaseModel):
    """Run progress and state inspection model."""
    run_id: str
    status: Literal["queued", "in_progress", "completed", "failed", "budget_exceeded"]
    progress_percentage: float = 0.0
    completed_subquestions: int = 0
    total_subquestions: int = 0
    total_tokens: int = 0
    current_node: Optional[str] = None
    error: Optional[str] = None
